/**
 * Carrier rate cards, for postage the 3PL does not bill (#34).
 *
 * DHL BPM Ground labels are generated by the 3PL against Rad & Happy's own DHL
 * eCommerce account, so they export at $0.00 and appear on no Evobox invoice.
 * That is 1,726 of 2,508 shipments over thirteen months — 69% of the shipment
 * base with no cost attached anywhere.
 *
 * The rate card closes that. Weight and destination postcode are already on
 * every shipment row, so postage is **computed per shipment**, not averaged
 * across them. That matters here: BPM parcels run from 0.06 to 8.15 lb and
 * reach every zone, and a single average over that spread would be wrong in
 * both directions at once.
 *
 * ## The rates are higher than they look
 *
 * A 2.5 lb parcel costs $7.08 to zone 1 and $10.74 to zone 8, before fuel.
 * An earlier estimate of ~$2.50-4.00 for "cheap book rate" was wrong by a
 * factor of three, which is exactly what the 3PL said when asked.
 */

export interface RateCard {
  carrier: string;
  service: string;
  effectiveFrom: string;
  /** Zones this card prices, in the order the rate arrays use. */
  zones: number[];
  /**
   * Ascending weight breaks. A parcel is charged at the first break greater
   * than or equal to its weight — carriers round up, never down or to nearest.
   */
  breaks: {
    weightLb: number;
    /** Added to the zone rate. A flat amount per break, not a percentage. */
    fuelSurchargeCents: number;
    /** Rate per zone, indexed the same as `zones`. */
    zoneRatesCents: number[];
  }[];
}

