export type RateOutcome =
  | { ok: true; cents: number; breakWeightLb: number; zone: number }
  | { ok: false; reason: "over_max_weight" | "unknown_zone" | "no_weight" };

/**
 * What one shipment's label costs.
 *
 * Returns a discriminated result rather than a number or null. An unrateable
 * shipment — no weight, a zone off the card, a parcel above the heaviest break
 * — must not collapse into the same value as a cheap one, which is how a
 * missing cost becomes a free shipment.
 */
export function rateShipment(card: RateCard, weightLb: number | null, zone: number | null): RateOutcome {
  if (weightLb === null || !Number.isFinite(weightLb) || weightLb <= 0) {
    return { ok: false, reason: "no_weight" };
  }
  if (zone === null) return { ok: false, reason: "unknown_zone" };

  const zoneIndex = card.zones.indexOf(zone);
  if (zoneIndex === -1) return { ok: false, reason: "unknown_zone" };

  // Carriers charge the first break at or above the actual weight.
  const chargedBreak = card.breaks.find((b) => weightLb <= b.weightLb);
  if (!chargedBreak) return { ok: false, reason: "over_max_weight" };

  return {
    ok: true,
    cents: chargedBreak.zoneRatesCents[zoneIndex] + chargedBreak.fuelSurchargeCents,
    breakWeightLb: chargedBreak.weightLb,
    zone,
  };
}

export interface RateBand {
  ok: true;
  minCents: number;
  maxCents: number;
  cheapestZone: number;
  dearestZone: number;
  breakWeightLb: number;
}

/**
 * The cost range across every zone, for use while the zone chart is unknown.
 *
 * A band is honest in a way a midpoint is not: it states what is actually
 * known. Zone 8 costs roughly a third more than zone 1 at these weights, so a
 * midpoint would be a number nobody can defend and everyone would quote.
 */
export function rateBand(card: RateCard, weightLb: number | null): RateBand | { ok: false; reason: RateOutcome extends { ok: false; reason: infer R } ? R : never } {
  const rated = card.zones
    .map((zone) => ({ zone, outcome: rateShipment(card, weightLb, zone) }))
    .filter((r): r is { zone: number; outcome: Extract<RateOutcome, { ok: true }> } => r.outcome.ok);

  if (rated.length === 0) {
    const probe = rateShipment(card, weightLb, card.zones[0]);
    return { ok: false, reason: probe.ok ? ("unknown_zone" as never) : (probe.reason as never) };
  }

  const cheapest = rated.reduce((a, b) => (b.outcome.cents < a.outcome.cents ? b : a));
  const dearest = rated.reduce((a, b) => (b.outcome.cents > a.outcome.cents ? b : a));
  return {
    ok: true,
    minCents: cheapest.outcome.cents,
    maxCents: dearest.outcome.cents,
    cheapestZone: cheapest.zone,
    dearestZone: dearest.zone,
    breakWeightLb: rated[0].outcome.breakWeightLb,
  };
}
